namespace Playground.Hello
{
    public class Person
    {
        public string Name { get; }

        // expression-bodied constructor
        public Person(string name) => Name = name;

        public Person() { Name = "Unknown"; }
    }
    public class Program
    {
        // expression-bodied method
        public static int Square(int x) => x * x;

        public Program() => Console.WriteLine("Program constructed (expression-bodied constructor)");

        static void Main(string[] args)
        {
            var person = new Person("Alice");

            // call method with block body
            PrintGreeting(person.Name);

            // method containing various constructs
            ControlFlowExamples();

            // local function (block-bodied)
            void LocalBlockFunction()
            {
                if (person.Name == "Alice")
                {
                    Console.WriteLine("Hello Alice (local function)");
                }
                else if (person.Name == "Bob")
                {
                    Console.WriteLine("Hello Bob (local function)");
                }
                else
                {
                    Console.WriteLine("Hello stranger (local function)");
                }

                for (int i = 0; i < 3; i++)
                {
                    Console.WriteLine($"Local loop i={i}");
                } // foreach over string (char)
                foreach (var c in person.Name)
                    Console.Write(c);

                Console.WriteLine();
            }

            LocalBlockFunction();

            // local function (expression-bodied)
            int Add(int a, int b) => a + b;
            Console.WriteLine($"Add local (expression-bodied): {Add(2, 3)}");
        }

        static void PrintGreeting(string name)
        {
            // nested if/else-if/else chain
            if (name.StartsWith("A"))
            {
                Console.WriteLine("Starts with A");
            }
            else if (name.Length > 4)
            {
                Console.WriteLine("Long name");
            }
            else
            {
                Console.WriteLine("Other name");
            }
        }
        static void ControlFlowExamples()
        {
            var list = new List<int> { 1, 2, 3, 4 };

            // for
            for (int i = 0; i < list.Count; i++)
            {
                Console.WriteLine($"for index {i} => {list[i]}");
            }

            // foreach (standard)
            foreach (var item in list)
            {
                Console.WriteLine($"foreach item {item}");
            }

            // foreach with deconstruction (ForEachVariable)
            var pairs = new List<(string, int)>() { ("a", 1), ("b", 2) };
            foreach (var (k, v) in pairs)
            {
                Console.WriteLine($"pair: {k} -> {v}");
            }

            // while
            int counter = 0;
            while (counter < 2)
            {
                Console.WriteLine($"while counter={counter}");
                counter++;
            }

            // do-while
            int dw = 2;
            do
            {
                Console.WriteLine($"do-while dw={dw}");
                dw--;
            } while (dw > 0);

            // nested control structures
            for (int i = 0; i < 2; i++)
            {
                if (i % 2 == 0)
                {
                    Console.WriteLine("even in nested for");
                }
                else
                {
                    Console.WriteLine("odd in nested for");
                }
            }
        }
        // regular method with block body
        public int Multiply(int a, int b)
        {
            return a * b;
        }
    }
}
